const raw = $input.first().json || {};
const html = String(raw.html || '');
const ids = [];
const re = /<tr[^>]+id="(\d+)"/gi;
let m;
while ((m = re.exec(html)) !== null) ids.push(m[1]);
const unique = [...new Set(ids)];
const pages = raw.pages_scraped;
const rowsApi = raw.rows_total;
return [{
  json: {
    success: raw.success !== false,
    pages_scraped: pages ?? null,
    rows_total_api: rowsApi ?? null,
    rows_counted_in_html: unique.length,
    verify_message: `pages_scraped=${pages ?? '?'} | rows_total=${rowsApi ?? '?'} | counted=${unique.length}`,
  },
}];

const fetchMeta = $('Pre-Works Fetch Summary').first().json || {};
const html = ($('Fetch Pre-Works Table HTML').first().json || {}).html || '';
const EASYBOP_BASE = 'https://easybop.co.uk';
const ASBESTOS_SUFFIX = '_wi_pw_24818_upload';
const WO_SUFFIX = '_wi_pw_24819_upload';
const UPRN_SUFFIX = '_property_ref';
const ADDR_SUFFIX = '_address';
const CORF_SUFFIX = '_client_order_reference';

function normCorf(v) {
  const raw = String(v ?? '').trim();
  if (!raw) return '';
  const t = raw.toLowerCase().replace(/\s+/g, '');
  const slash = t.match(/^(\d+)\/(\d+)$/);
  if (slash) return parseInt(slash[1], 10) + '/' + parseInt(slash[2], 10);
  const under = t.match(/^(\d+)_(\d+)$/);
  if (under) return parseInt(under[1], 10) + '/' + parseInt(under[2], 10);
  return t;
}
function cellClass(attrs) {
  const m = String(attrs || '').match(/class="([^"]*)"/i);
  if (!m) return '';
  return m[1].split(/\s+/).find(c => c.startsWith('jqgrid_bg_')) || '';
}
function cellTitle(attrs) {
  const m = String(attrs || '').match(/title="([^"]*)"/i);
  return m ? m[1].trim() : '';
}
function absHref(href) {
  const h = String(href || '').replace(/&amp;/g, '&');
  if (!h) return '';
  if (h.startsWith('http')) return h;
  return EASYBOP_BASE + '/' + h.replace(/^\//, '');
}
function isMsgDownloadUrl(url) {
  const u = decodeURIComponent(String(url || '')).toLowerCase();
  if (!u) return false;
  if (/filename_orig=[^&]*\.msg\b/i.test(u)) return true;
  if (/\.msg(?:\?|$|&)/i.test(u)) return true;
  if (/file=[^&]*\.msg\b/i.test(u)) return true;
  return false;
}
function cellMsgHref(cell) {
  if (!cell) return null;
  const blob = (cell.attrs || '') + (cell.inner || '');
  const hrefs = [];
  const re = /href="([^"]+)"/gi;
  let m;
  while ((m = re.exec(blob)) !== null) {
    const href = absHref(m[1]);
    if (href) hrefs.push(href);
  }
  for (const href of hrefs) {
    if (isMsgDownloadUrl(href)) return href;
  }
  return null;
}

const trRegex = /<tr[^>]+id="(\d+)"[^>]*>([\s\S]*?)<\/tr>/gi;
const rows = [];
let trMatch;
while ((trMatch = trRegex.exec(html)) !== null) {
  const rowId = trMatch[1];
  const rowHtml = trMatch[2];
  const cells = {};
  const tdRegex = /<td([^>]+)>([\s\S]*?)<\/td>/gi;
  let tdMatch;
  while ((tdMatch = tdRegex.exec(rowHtml)) !== null) {
    const keyMatch = tdMatch[1].match(/aria-describedby="([^"]+)"/i);
    if (!keyMatch) continue;
    cells[keyMatch[1]] = { attrs: tdMatch[1], inner: tdMatch[2] };
  }
  function getCell(suffix) {
    for (const [key, val] of Object.entries(cells)) {
      if (key.endsWith(suffix)) return val;
    }
    return null;
  }

  const asbCell = getCell(ASBESTOS_SUFFIX);
  if (!asbCell) continue;
  const asbClass = cellClass(asbCell.attrs);
  if (!asbClass.includes('red')) continue;

  const woCell = getCell(WO_SUFFIX);
  const woClass = woCell ? cellClass(woCell.attrs) : '';
  const woMsgUrl = cellMsgHref(woCell);

  const corfRaw = cellTitle(getCell(CORF_SUFFIX)?.attrs);
  const corf = normCorf(corfRaw) || normCorf(corfRaw.replace(/_/g, '/'));
  rows.push({
    pre_work_id: rowId,
    uprn: cellTitle(getCell(UPRN_SUFFIX)?.attrs),
    address: cellTitle(getCell(ADDR_SUFFIX)?.attrs),
    client_order_reference: corfRaw || corf,
    corf,
    asbestos_class: asbClass,
    works_order_url: woMsgUrl,
    wo_upload_class: woClass,
    wo_msg_on_preworks: !!(woClass.includes('green') && woMsgUrl),
  });
}

console.log(`${fetchMeta.verify_message || ''} | Red asbestos rows=${rows.length} | with green WO .msg=${rows.filter(r => r.wo_msg_on_preworks).length}`);
if (!rows.length) {
  return [{ json: { _no_red_rows: true, red_count: 0, message: 'No red Global Asbestos Survey rows on pre-works report.' } }];
}
return rows.map(r => ({ json: r }));

function bodyFrom(resp) {
  let body = resp.body ?? resp.data ?? resp;
  if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = {}; } }
  if (body && body.body && body.items === undefined && body.total === undefined) body = body.body;
  return body || {};
}
function normCorf(v) {
  const raw = String(v ?? '').trim();
  if (!raw) return '';
  const t = raw.toLowerCase().replace(/\s+/g, '');
  const slash = t.match(/^(\d+)\/(\d+)$/);
  if (slash) return parseInt(slash[1], 10) + '/' + parseInt(slash[2], 10);
  const digits = t.replace(/\D/g, '');
  if (digits.length >= 4) return String(parseInt(digits, 10));
  return t;
}
const resp = $input.first().json || {};
const data = bodyFrom(resp);
const items = Array.isArray(data.items) ? data.items : [];
const corfToWorksId = {};
for (const item of items) {
  const wid = String(item.works_id || '').trim();
  if (!wid) continue;
  const corf = normCorf(item.client_order_reference || '');
  if (corf) corfToWorksId[corf] = wid;
}
const sd = $getWorkflowStaticData('global');
sd.corfToWorksId = corfToWorksId;
return [{ json: { works_index_total: data.total ?? items.length, corf_map_size: Object.keys(corfToWorksId).length } }];

function normCorf(v) {
  const raw = String(v ?? '').trim();
  if (!raw) return '';
  const t = raw.toLowerCase().replace(/\s+/g, '');
  const slash = t.match(/^(\d+)\/(\d+)$/);
  if (slash) return parseInt(slash[1], 10) + '/' + parseInt(slash[2], 10);
  const under = t.match(/^(\d+)_(\d+)$/);
  if (under) return parseInt(under[1], 10) + '/' + parseInt(under[2], 10);
  return t;
}
function normBypassRef(raw) {
  const digits = String(raw ?? '').replace(/[^0-9]/g, '');
  if (!digits) return '';
  return String(parseInt(digits, 10));
}
function isYes(v) {
  const t = String(v ?? '').trim().toLowerCase();
  return t === 'yes' || t === 'y' || t === 'true' || t === '1';
}
function sliceAfterJobDetails(text) {
  const t = String(text || '');
  const m = t.match(/Job\s*Details\s*[:-]/i);
  if (!m || m.index == null) return '';
  return t.slice(m.index);
}
function extractBoqRefsFromText(text) {
  const section = sliceAfterJobDetails(text);
  if (!section) return [];
  const refs = [];
  const seen = new Set();
  const re = /\b(\d{1,3}[A-Z]{2})(\d{4,6})\b/gi;
  let m;
  while ((m = re.exec(section)) !== null) {
    const ref = String(parseInt(m[2], 10));
    if (!seen.has(ref)) { seen.add(ref); refs.push(ref); }
  }
  return refs;
}
function corfInSubject(corf, subject) {
  const c = normCorf(corf);
  if (!c) return false;
  const s = String(subject || '');
  if (s.includes(c)) return true;
  const parts = c.split('/');
  if (parts.length === 2) {
    const alt = parts[0] + '_' + parts[1];
    if (s.includes(alt)) return true;
  }
  return false;
}

const bypassRows = $('Read BOQ-Bypass-list').all().map(i => i.json || {});
const allowed = new Set();
for (const row of bypassRows) {
  const ref = normBypassRef(row.Reference ?? row['BOQ Item Ref.'] ?? row['BOQ Item Ref'] ?? '');
  const bypass = row['Bypass for Asbestos'] ?? row['Bypass for asbestos'] ?? row.Bypass;
  if (ref && isYes(bypass)) allowed.add(ref);
}

const agg = $('Aggregate Extract Batch').first().json || {};
const prepared = $('Prepare Bypass Candidates').all()
  .map(i => i.json || {})
  .filter(j => !j._skip);
let batch = $('POST extract-msg-from-urls-batch').first().json || {};
if (batch.body && !batch.results) batch = batch.body;

const extractByCorf = {};
for (const r of (batch.results || [])) {
  const k = normCorf(r.corf);
  if (k) extractByCorf[k] = r;
}

const out = [];
for (const skipped of (agg._extract_skipped || [])) {
  out.push({ json: skipped });
}

for (const base of prepared) {
  const k = normCorf(base.corf);
  const extract = extractByCorf[k] || {};
  if (!extract.success) {
    out.push({ json: {
      pre_work_id: base.pre_work_id,
      corf: base.corf,
      works_id: base.works_id,
      address: base.address,
      bypass_eligible: false,
      bypass_reason: `extract_error: ${extract.error || 'missing batch result'}`,
    }});
    continue;
  }
  const body = extract.body_text || '';
  const subject = extract.subject || '';
  if (!corfInSubject(base.corf, subject)) {
    out.push({ json: {
      pre_work_id: base.pre_work_id,
      corf: base.corf,
      works_id: base.works_id,
      address: base.address,
      bypass_eligible: false,
      bypass_reason: `subject_mismatch: expected ${base.corf} got ${subject}`,
      content_md5: extract.content_md5,
    }});
    continue;
  }
  const boqRefs = extractBoqRefsFromText(body);
  const non = boqRefs.filter(r => !allowed.has(r));
  const eligible = boqRefs.length > 0 && non.length === 0;
  let reason = 'all_refs_allowlisted';
  if (!sliceAfterJobDetails(body)) reason = 'no_job_details_section';
  else if (!boqRefs.length) reason = 'no_boq_refs_in_job_details';
  else if (non.length) reason = `refs_not_allowlisted: ${non.join(',')}`;
  out.push({ json: {
    pre_work_id: base.pre_work_id,
    corf: base.corf,
    works_id: base.works_id,
    address: base.address,
    body_text_len: body.length,
    content_md5: extract.content_md5,
    boq_refs: boqRefs,
    bypass_eligible: eligible,
    bypass_reason: reason,
    non_bypass_refs: non,
    allowed_bypass_count: allowed.size,
  }});
}
return out;

const apiBase = String($('Set API URL').first().json.api_base_url || '').replace(/\/+$/, '');
const rows = $('Check Bypass Eligibility').all();
const items = [];
const batchMeta = [];
const skipped = [];
for (const item of rows) {
  const j = item.json || {};
  const base = { pre_work_id: j.pre_work_id, corf: j.corf, works_id: j.works_id, boq_refs: j.boq_refs };
  if (!j.bypass_eligible) {
    skipped.push({ ...base, _status: `SKIPPED: ${j.bypass_reason || 'not eligible'}`, _api_success: false });
    continue;
  }
  const corf = String(j.corf || '').trim();
  const wid = String(j.works_id || '').trim();
  if (!corf || !wid) {
    skipped.push({ ...base, _status: 'ERROR: Missing corf/works_id', _api_success: false });
    continue;
  }
  items.push({ corf, works_id: wid });
  batchMeta.push({ ...base, bypass_reason: j.bypass_reason });
}
return [{
  json: {
    _api_url: `${apiBase}/asbestos-bypass/batch`,
    _skipped: skipped,
    _batch_meta: batchMeta,
    _batch_body: { items, contract_id: '321129', timeout_ms: 45000 },
    _item_count: items.length,
    _skipped_count: skipped.length,
  },
}];

const agg = $('Aggregate Bypass Batch').first().json;
const skipped = agg._skipped || [];
const batchMeta = agg._batch_meta || [];
function extractResults(resp) {
  const statusCode = resp.statusCode ?? resp.status ?? 0;
  let body = resp.body ?? resp.data ?? resp;
  if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = {}; } }
  if (body && typeof body === 'object' && body.body && !body.results) body = body.body;
  return { statusCode, body: body || {}, results: Array.isArray(body?.results) ? body.results : [] };
}
function mapApiResult(r, meta) {
  const ok = !!(r.success || r.bypassed || r.already_bypassed);
  const status = ok ? 'true' : `ERROR: ${r.error || r.message || 'Unknown error'}`;
  return {
    pre_work_id: meta.pre_work_id,
    corf: r.corf || meta.corf,
    works_id: r.works_id || meta.works_id,
    boq_refs: meta.boq_refs,
    _status: status,
    _api_success: ok,
    _bypassed: !!r.bypassed,
    _already_bypassed: !!r.already_bypassed,
  };
}
let apiResults = [];
if (agg._item_count > 0) {
  const resp = ($('POST asbestos-bypass batch').first().json || {});
  const { results } = extractResults(resp);
  for (let idx = 0; idx < results.length; idx++) {
    apiResults.push(mapApiResult(results[idx], batchMeta[idx] || {}));
  }
}
const all = [...skipped, ...apiResults];
return all.map(j => ({ json: j }));

const rows = $('Expand Batch Results').all().map(i => i.json || {});
let bypassed = 0, already = 0, skipped = 0, errors = 0;
const errorDetails = [];
for (const r of rows) {
  const status = String(r._status ?? '').trim();
  if (status === 'true') {
    if (r._already_bypassed) already++;
    else if (r._bypassed) bypassed++;
    else already++;
  } else if (status.startsWith('SKIPPED:')) skipped++;
  else if (status.startsWith('ERROR:')) { errors++; errorDetails.push({ corf: r.corf, works_id: r.works_id, error: status }); }
}
return [{ json: {
  workflow: 'pre_works_asbestos_bypass',
  total_results: rows.length,
  bypassed,
  already_bypassed: already,
  skipped_not_eligible: skipped,
  errors,
  error_details: errorDetails,
} }];

const rows = $('Parse Red Asbestos Rows').all().map(i => i.json || {}).filter(r => !r._no_red_rows);
const sd = $getWorkflowStaticData('global');
const corfToWorksId = sd.corfToWorksId || {};

function normCorf(v) {
  const raw = String(v ?? '').trim();
  if (!raw) return '';
  const t = raw.toLowerCase().replace(/\s+/g, '');
  const slash = t.match(/^(\d+)\/(\d+)$/);
  if (slash) return parseInt(slash[1], 10) + '/' + parseInt(slash[2], 10);
  const under = t.match(/^(\d+)_(\d+)$/);
  if (under) return parseInt(under[1], 10) + '/' + parseInt(under[2], 10);
  return t;
}
function isMsgDownloadUrl(url) {
  const u = decodeURIComponent(String(url || '')).toLowerCase();
  if (!u) return false;
  return /filename_orig=[^&]*\.msg\b/i.test(u) || /\.msg(?:\?|$|&)/i.test(u) || /file=[^&]*\.msg\b/i.test(u);
}

const pending = [];
const skipped = [];
for (const row of rows) {
  const corfRaw = String(row.client_order_reference || row.corf || '').trim();
  const corf = normCorf(corfRaw) || corfRaw;
  if (!corf) {
    skipped.push({ pre_work_id: row.pre_work_id, reason: 'no_corf' });
    continue;
  }
  const woClass = String(row.wo_upload_class || '');
  const woUrl = String(row.works_order_url || '').trim();
  if (!woClass.includes('green')) {
    skipped.push({ pre_work_id: row.pre_work_id, corf, address: row.address, reason: 'wo_not_green_on_preworks' });
    continue;
  }
  if (!woUrl || !isMsgDownloadUrl(woUrl)) {
    skipped.push({ pre_work_id: row.pre_work_id, corf, address: row.address, reason: 'no_wo_msg_link_on_preworks', wo_upload_class: woClass });
    continue;
  }
  const works_id = corfToWorksId[corf] || '';
  if (!works_id) {
    skipped.push({ pre_work_id: row.pre_work_id, corf, address: row.address, reason: 'no_works_id' });
    continue;
  }
  pending.push({
    json: {
      _skip: false,
      pre_work_id: row.pre_work_id,
      corf: corfRaw || corf,
      works_id,
      address: row.address || '',
      uprn: row.uprn || '',
      works_order_url: woUrl,
    },
  });
}

if (!pending.length) {
  return [{ json: { _skip: true, message: 'No pending asbestos bypass candidates (need red asbestos + green WO .msg on pre-works).', skipped_count: skipped.length, skipped } }];
}
return pending;

const apiBase = String($('Set API URL').first().json.api_base_url || '').replace(/\/+$/, '');
const rows = $('Prepare Bypass Candidates').all().filter(i => !(i.json || {})._skip);
const items = [];
const skipped = [];
for (const item of rows) {
  const j = item.json || {};
  const base = {
    pre_work_id: j.pre_work_id,
    corf: j.corf,
    works_id: j.works_id,
    address: j.address,
    uprn: j.uprn,
    works_order_url: j.works_order_url,
  };
  const corf = String(j.corf || '').trim();
  const url = String(j.works_order_url || '').trim();
  if (!corf || !url) {
    skipped.push({
      ...base,
      bypass_eligible: false,
      bypass_reason: 'missing_corf_or_works_order_url',
      _status: 'SKIPPED: missing_corf_or_works_order_url',
      _api_success: false,
    });
    continue;
  }
  items.push({ corf, works_order_url: url });
}
return [{
  json: {
    _api_url: `${apiBase}/pre-works/extract-msg-from-urls-batch`,
    _extract_body: { items },
    _extract_skipped: skipped,
    _extract_count: items.length,
    _skipped_prepare_count: skipped.length,
  },
}];
